        UnlockDisplay(dpy);
        SyncHandle();
        return NULL;
    }

    _XReadPad(dpy, buf, nbytes);

    output = (RROutput *)(mon + nmon);

    for (m = 0; m < nmon; m++)
    {
        xmon = (xRRMonitorInfo *)buf;
        mon[m].name = xmon->name;
        mon[m].primary = xmon->primary;
        mon[m].automatic = xmon->automatic;
        mon[m].noutput = xmon->noutput;
        mon[m].x = xmon->x;
        mon[m].y = xmon->y;
        mon[m].width = xmon->width;
        mon[m].height = xmon->height;
        mon[m].mwidth = xmon->widthInMillimeters;
        mon[m].mheight = xmon->heightInMillimeters;
        mon[m].outputs = output;
        buf += SIZEOF(xRRMonitorInfo);
        xoutput = (CARD32 *)buf;
        // Проверка, что xmon->noutput не превышает оставшееся место
        if (xmon->noutput < 0 || xmon->noutput > noutput || (buf + xmon->noutput * 4) > (buf_head + nbytes))
        {
            Xfree(buf_head);
            Xfree(mon);
            _XEatDataWords(dpy, rep.length);
            UnlockDisplay(dpy);
            SyncHandle();
            return NULL;
        }
        for (o = 0; o < xmon->noutput; o++)
            output[o] = xoutput[o];
        output += xmon->noutput;
        buf += xmon->noutput * 4;
    }
    Xfree(buf_head);
    *nmonitors = nmon;
    return mon;
}

